from fractions import Fraction as Fr
A=[[2,3,1],[4,5,-3],[-2,1,6]]; b=[5,2,7]; n=3
M=[[Fr(v) for v in r]+[Fr(c)] for r,c in zip(A,b)]
for c in range(n):
    for r in range(c+1,n):
        m=M[r][c]/M[c][c]; M[r]=[u-m*v for u,v in zip(M[r],M[c])]
x=[0]*n
for i in reversed(range(n)):
    x[i]=(M[i][n]-sum(M[i][j]*x[j] for j in range(i+1,n)))/M[i][i]
