from itertools import combinations
R=set("ABCDE"); F=[("A","B"),("C","D"),("BD","E"),("E","A")]
def cl(s):
    s=set(s)
    while True:
        n=set(s)
        for l,r in F:
            if set(l)<=n: n|=set(r)
        if n==s: return s
        s=n
sk=[set(c) for k in range(1,6) for c in combinations("ABCDE",k) if cl(c)==R]
keys=[k for k in sk if not any(o<k for o in sk)]
print(sorted("".join(sorted(k)) for k in keys),len(set().union(*keys)))
